# ============================================================
#  DeepSeek Harness One-Click Launcher generator
#  Generates in THIS script's folder:
#    start-dsh.bat        double-click to start DeepSeek Harness
#    DeepSeekHarness.exe  same, as an .exe wrapper
#  Usage: right-click this file -> "Run with PowerShell"
#  Requirements: Windows (PowerShell is built in). No Node needed
#  to GENERATE; the launcher itself auto-installs dsh on first run.
# ============================================================
$dir = if ($PSScriptRoot) { $PSScriptRoot } else { (Get-Location).Path }

# DeepSeekHarness.exe (launcher shell that opens start-dsh.bat)
$exeB64 = ''

$lines = @(
  '@echo off',
  'setlocal',
  'title DeepSeek Harness',
  'cd /d "%~dp0"',
  '',
  'rem create DeepSeekHarness.exe on first run (PowerShell ships with every Windows)',
  'if exist "DeepSeekHarness.exe" goto haveexe',
  'powershell -NoProfile -ExecutionPolicy Bypass -Command "[IO.File]::WriteAllBytes(''%~dp0DeepSeekHarness.exe'',[Convert]::FromBase64String(''__B64__''))"',
  ':haveexe',
  '',
  'where npm >nul 2>nul',
  'if errorlevel 1 goto nonpm',
  '',
  'rem auto-install dsh on first run so the launcher works in any fresh folder',
  'if exist "node_modules\@deepseek-ai\dsh" goto havedeps',
  'if not exist package.json echo {}> package.json',
  'echo First run: installing dsh, please wait (network required)...',
  'call npm install --no-audit --no-fund -D @deepseek-ai/dsh',
  'if errorlevel 1 goto npmfail',
  ':havedeps',
  '',
  'echo ============================================',
  'echo   DeepSeek Harness launcher',
  'echo   Keep this window open while using it.',
  'echo   Open the URL printed below in your browser.',
  'echo ============================================',
  'echo.',
  'call npm run dsh',
  'echo.',
  'echo Harness stopped.',
  'pause',
  'exit /b 0',
  '',
  ':nonpm',
  'echo [ERROR] npm not found on PATH. Install Node.js first: https://nodejs.org',
  'pause',
  'exit /b 1',
  '',
  ':npmfail',
  'echo [ERROR] npm install failed. Check your network and retry.',
  'pause',
  'exit /b 1'
)

$bat = ($lines -join "`r`n") + "`r`n"
$bat = $bat.Replace('__B64__', $exeB64)

[IO.File]::WriteAllBytes((Join-Path $dir 'DeepSeekHarness.exe'), [Convert]::FromBase64String($exeB64))
[IO.File]::WriteAllText((Join-Path $dir 'start-dsh.bat'), $bat)

Write-Host 'Done:'
Write-Host '  start-dsh.bat        (double-click to start DeepSeek Harness)'
Write-Host '  DeepSeekHarness.exe  (same, as an exe)'
